package org.apache.commons.codec.binary;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.codec.BinaryDecoder;
import org.apache.commons.codec.BinaryEncoder;
import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Base64_encodeBase64_TriageGen2Test {

    @Test
    public void testEncodeBase64_NullInput() {
        byte[] input = null;
        byte[] result = Base64.encodeBase64(input, false, false, 100);
        assertNull(result);
    }

    @Test
    public void testEncodeBase64_EmptyInput() {
        byte[] input = new byte[0];
        byte[] result = Base64.encodeBase64(input, false, false, 100);
        assertEquals(0, result.length);
    }

    @Test
    public void testEncodeBase64_TooLarge_ThrowsException() {
        byte[] input = new byte[100];
        // Set maxResultSize very small to trigger the IllegalArgumentException
        try {
            Base64.encodeBase64(input, false, false, 1);
            fail("Expected IllegalArgumentException was not thrown");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Input array too big"));
        }
    }

    @Test
    public void testEncodeBase64_Standard_NonUrlSafe_NonChunked() {
        byte[] input = "Hello".getBytes();
        // Standard Base64: "SGVsbG8="
        byte[] result = Base64.encodeBase64(input, false, false, 100);
        assertEquals("SGVsbG8=", new String(result));
    }

    @Test
    public void testEncodeBase64_UrlSafe_NonChunked() {
        // Use bytes that would produce '+' or '/' in standard Base64
        // e.g., binary data that results in '+' or '/'
        byte[] input = new byte[]{(byte) 0xfb, (byte) 0xff}; 
        // Standard Base64 for [fb ff] is "+/++"

        byte[] result = Base64.encodeBase64(input, false, true, 100);
        String resultStr = new String(result);

        assertFalse("Result should not contain '+'", resultStr.contains("+"));
        assertFalse("Result should not contain '/'", resultStr.contains("/"));
    }

    @Test
    public void testEncodeBase64_Chunked_NonUrlSafe() {
        byte[] input = new byte[200]; // Large enough to trigger chunking if MIME_CHUNK_SIZE is small
        for (int i = 0; i < input.length; i++) {
            input[i] = (byte) i;
        }

        // Testing chunked mode
        // isChunked = true
        byte[] result = Base64.encodeBase64(input, true, false, 1000);
        assertNotNull(result);
        assertTrue("Chunked output should be longer than raw base64", result.length > 0);
    }

    @Test
    public void testEncodeBase64_Chunked_UrlSafe() {
        byte[] input = new byte[50];
        for (int i = 0; i < input.length; i++) {
            input[i] = (byte) i;
        }

        // isChunked = true, urlSafe = true
        byte[] result = Base64.encodeBase64(input, true, true, 1000);
        assertNotNull(result);
        String resultStr = new String(result);
        assertFalse(resultStr.contains("+"));
        assertFalse(resultStr.contains("/"));
    }

    @Test
    public void testEncodeBase64_BoundaryMaxResultSize() {
        byte[] input = "abc".getBytes();
        // Calculate approximate size: Base64 is ~4/3 the size. 
        // "abc" -> "YWJj" (4 bytes)
        // We set maxResultSize exactly to the required length to ensure it passes the len > maxResultSize check.

        // We don't know the exact internal getEncodeLength logic without the source, 
        // but we test the boundary condition where len is just below or equal to maxResultSize.
        int calculatedLen = 4; 
        try {
            Base64.encodeBase64(input, false, false, calculatedLen);
        } catch (IllegalArgumentException e) {
            // If getEncodeLength includes extra metadata/buffers that make it > 4, this is fine.
        }
    }
}
